  onClick: () => void;
  disabled?: boolean;
  children: ReactNode;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      className="flex min-h-12 items-center gap-1.5 rounded-xl border-2 border-slate-300 bg-white px-3 text-sm font-semibold text-slate-800 disabled:opacity-50"
