**Writes — [journeyService.ts](src/services/journeyService.ts)** (every one goes through `createDoc`/`updateDoc`, so each has an `audit` stamp and an `auditLog` entry)

```ts
export async function registerMother(input: RegisterMotherInput, actor: Actor) {
  const at = nowIso();
  const mother: Mother = { id: newId('mtr'), name: input.name.trim(), village: input.village,
    registeredBy: actor.id, language: input.language, consentStatus: 'pending',
    expectedDeliveryMonth: input.expectedDeliveryMonth, synthetic: SYNTHETIC_FLAG, audit: newAudit(actor, at) };
  const card: JourneyCard = { id: newId('jrn'), motherId: mother.id,
    milestones: milestonesFromTemplate(), visits: [], synthetic: SYNTHETIC_FLAG, audit: newAudit(actor, at) };
  await createDoc(firestoreStore, COLLECTIONS.mothers, mother);
  await createDoc(firestoreStore, COLLECTIONS.journeyCards, card);
  return { mother, card };
}

export async function saveMilestoneStatus(card, templateId, status, doneDate, actor) {
  return updateDoc(firestoreStore, COLLECTIONS.journeyCards, card,
    { milestones: withMilestoneStatus(card.milestones, templateId, status, doneDate) }, actor);
}

export async function addVisit(card, input, actor) {
  const visit: Visit = { id: newId('vst'), date: input.date, enteredBy: actor.id,
    enteredAt: nowIso(), note: input.note.trim(), revisions: [] };
  return updateDoc(firestoreStore, COLLECTIONS.journeyCards, card, { visits: [...card.visits, visit] }, actor);
}

/** Correct a visit: the previous date/note are pushed into `revisions`. */
export async function editVisit(card, visitId, input, actor) {
  const target = card.visits.find((v) => v.id === visitId);
  if (!target) throw new Error(`Visit ${visitId} not found`);
  const revision: VisitRevision = { date: target.date, note: target.note, editedBy: actor.id, editedAt: nowIso() };
  const visits = card.visits.map((v) => v.id === visitId
    ? { ...v, date: input.date, note: input.note.trim(), revisions: [...v.revisions, revision] } : v);
  return updateDoc(firestoreStore, COLLECTIONS.journeyCards, card, { visits }, actor);
}
// There is deliberately no delete function anywhere in this file.
