import {
  createContext,
  useContext,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import type { Role } from '../data/model';
import type { Actor } from '../services/audit';

type WorkerRole = 'asha' | 'anm';

/** Demo identities (seed ids). There is no sign-in yet, so each role area uses
 * one of the synthetic workers/mothers from the seed. Phone-OTP auth will
 * replace this context in a later step — nothing here is real identity.
 */
const DEMO_DEFAULT_ID: Record<WorkerRole, string> = {
  asha: 'usr_asha_meena',
  anm: 'usr_anm_priya',
};

const STORAGE_KEY = 'maasetu.demo-identity';

type Identity = {
  worker: Record<WorkerRole, string>;
  mother: string;
};

function loadIdentity(): Identity {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as Partial<Identity>;
      return {
        worker: { ...DEMO_DEFAULT_ID.worker, ...(parsed.worker || {}) },
        mother: parsed.mother ?? DEMO_DEFAULT_ID.mother ?? 'mtr_savitri',
      };
    }
  } catch {
    // Corrupt or unavailable storage: fall back to the demo defaults.
  }
  return {
    worker: { ...DEMO_DEFAULT_ID.worker },
    mother: DEMO_DEFAULT_ID.mother ?? 'mtr_savitri',
  };
}

interface SessionValue {
  workerIdFor: (role: WorkerRole) => string;
  setWorkerId: (role: WorkerRole, id: string) => void;
  demoMotherId: string;
  setDemoMotherId: (id: string) => void;
  actorFor: (role: Role) => Actor;
}

const SessionContext = createContext<SessionValue | null>(null);

export function SessionProvider({ children }: { children: ReactNode }) {
  const [identity, setIdentity] = useState<Identity>(loadIdentity);

  useEffect(() => {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(identity));
  }, [identity]);

  const value = useMemo<SessionValue>(
    () => ({
      workerIdFor: (role) => identity.worker[role],
      setWorkerId: (role, id) => setIdentity((prev) => ({
        ...prev,
        worker: { ...prev.worker, [role]: id },
      })),
      demoMotherId: identity.mother,
      setDemoMotherId: (id) => setIdentity((prev) => ({
        ...prev,
        mother: id,
      })),
      actorFor: (role) => ({ id: identity.worker[role] || '', role }),
    }),
    [identity],
  );

  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>;
}

export function useSession(): SessionValue {
  const ctx = useContext(SessionContext);
  if (!ctx) throw new Error('useSession must be used inside <SessionProvider>');
  return ctx;
}
